args.script:
cd experiment && find . -type f \( -name "*.txt" -o -name "*.csv" -o -name "*.log" \) -print0 | xargs -0 awk '
FNR==1 { ext = (FILENAME ~ /\.txt$/ ? "txt" : (FILENAME ~ /\.csv$/ ? "csv" : "log")) }
/^[[:space:]]*$/ { next }
{ count[ext]++ }
END { print count["txt"], count["csv"], count["log"] }'
